for m in s m0 m1 m2 m3 m4 m5; do echo "-- $m"; grep -oE 'claude-[a-z0-9.-]+|kimi-k[0-9]+|gpt-[0-9.]+-?[a-z]*|[a-z]+-[0-9]+(\.[0-9]+)?-(sol|fast|mini)' reports/usage/$m.md | sort | uniq -c; done
