echo "--- 'blocking' severity strings inside user-testing discoveredIssues"
for f in s m0 m1 m2 m3 m4 m5; do echo "$f: $(jq -c '[.discoveredIssues? // [] | if type=="array" then .[] else empty end | select((tostring|test("\"(severity|blocking)\":\\s*(\"blocking\"|true)"))) ] | length' $f/user-testing/synthesis.json)"; done
